declare(strict_types=1);require_once dirname(__DIR__,2).'/config.php';require_once BASE_PATH.'/shared/accounts-import-vat.php';import_vat_require_owner();import_vat_schema_ready();header('Cache-Control:no-store');
function im_reply(array$d,int$s=200):void{http_response_code($s);header('Content-Type:application/json; charset=utf-8');echo json_encode($d,JSON_UNESCAPED_SLASHES);exit;}
function im_date(string$v):bool{return(bool)preg_match('/^\d{4}-\d{2}-\d{2}$/',$v)&&strtotime($v)!==false;}
function im_statement_upload():array{
 if(!isset($_FILES['statement'])||!is_uploaded_file((string)$_FILES['statement']['tmp_name']))throw new RuntimeException('Select a NamRA statement to upload.');$file=$_FILES['statement'];if((int)$file['error']!==UPLOAD_ERR_OK)throw new RuntimeException('The NamRA statement did not upload successfully.');$tmp=(string)$file['tmp_name'];$size=(int)$file['size'];if($size<=0||$size>30*1024*1024)throw new RuntimeException('Statements must be no larger than 30 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($tmp)?:'';$allowed=['application/pdf'=>'pdf','text/csv'=>'csv','text/plain'=>'csv','application/vnd.ms-excel'=>'csv'];if(!isset($allowed[$mime]))throw new RuntimeException('Upload a machine-readable PDF or CSV NamRA statement. Excel files require a verified statement sample before support can be enabled.');$hash=hash_file('sha256',$tmp);$q=db()->prepare('SELECT id FROM accounts_import_vat_statements WHERE sha256=?');$q->execute([$hash]);if($existing=(int)$q->fetchColumn())return['duplicate'=>true,'statement'=>import_vat_statement($existing),'message'=>'This exact statement was already uploaded. No duplicate records were created.'];$dir=BASE_PATH.'/uploads/import-vat-statements';if(!is_dir($dir)&&!mkdir($dir,0750,true)&&!is_dir($dir))throw new RuntimeException('Protected statement storage is unavailable.');$stored=bin2hex(random_bytes(24)).'.'.$allowed[$mime];if(!move_uploaded_file($tmp,$dir.'/'.$stored))throw new RuntimeException('The NamRA statement could not be stored.');$u=current_user();$status='needs_review';$message='Statement stored securely. Review is required before any accounting records can be created.';$rows=[];if($allowed[$mime]==='csv'){try{$rows=import_vat_csv_rows($dir.'/'.$stored);$message=count($rows).' statement rows detected from named CSV columns. Review every row before confirmation.';}catch(Throwable$e){$status='parse_failed';$message=$e->getMessage();}}else{$message='PDF stored securely. A real NamRA statement sample is required to validate its layout before automatic row extraction can be enabled. No records were posted.';}db()->beginTransaction();try{$counts=['liability'=>0,'payment'=>0,'unknown'=>0];foreach($rows as$r)$counts[$r['row_kind']]++;db()->prepare('INSERT INTO accounts_import_vat_statements(original_filename,stored_filename,mime_type,file_size,sha256,statement_period,status,parse_message,rows_detected,liabilities_detected,payments_detected,needs_review,uploaded_by,uploaded_by_name)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([mb_substr(basename((string)$file['name']),0,255),$stored,$mime,$size,$hash,$_POST['statement_period']??null,$status,$message,count($rows),$counts['liability'],$counts['payment'],$counts['unknown'],(int)$u['id'],(string)$u['name']]);$id=(int)db()->lastInsertId();$insert=db()->prepare('INSERT INTO accounts_import_vat_statement_rows(statement_id,row_number,transaction_date,due_date,reference,description,debit,credit,import_vat_amount,other_charge_amount,payment_amount,row_kind,confidence,match_status,source_json)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');foreach($rows as$r){$match=$r['match_status'];if($r['row_kind']==='liability'&&$r['reference']!==''){$d=db()->prepare('SELECT id FROM accounts_import_vat_liabilities WHERE reference=? AND deleted_at IS NULL');$d->execute([$r['reference']]);if($d->fetchColumn())$match='already_imported';}$insert->execute([$id,$r['row_number'],$r['transaction_date'],$r['due_date'],$r['reference'],$r['description'],$r['debit'],$r['credit'],$r['import_vat_amount'],$r['other_charge_amount'],$r['payment_amount'],$r['row_kind'],$r['confidence'],$match,$r['source_json']]);}import_vat_statement_audit($id,'statement_uploaded',['hash'=>$hash,'rows'=>count($rows),'mime'=>$mime]);db()->commit();return['duplicate'=>false,'statement'=>import_vat_statement($id),'message'=>$message];}catch(Throwable$e){db()->rollBack();@unlink($dir.'/'.$stored);throw$e;}
}
function im_confirm_statement(int$id):array{$statement=import_vat_statement($id);if(!$statement)throw new RuntimeException('Statement not found.');if($statement['confirmed_at'])return$statement;$active=array_values(array_filter($statement['rows'],fn($r)=>!(int)$r['excluded']));if(!$active)throw new RuntimeException('There are no reviewed rows to import.');foreach($active as$r){if($r['row_kind']==='unknown')throw new RuntimeException('Classify or exclude row '.$r['row_number'].' before confirmation.');if($r['confidence']==='low')throw new RuntimeException('Review or exclude low-confidence row '.$r['row_number'].' before confirmation.');if($r['row_kind']==='liability'&&(!$r['transaction_date']||!$r['due_date']||trim((string)$r['reference'])===''||(float)$r['import_vat_amount']<=0))throw new RuntimeException('Liability row '.$r['row_number'].' needs a date, due date, reference and Import VAT amount.');if($r['row_kind']==='payment'&&(!(int)$r['matched_import_id']||(float)$r['payment_amount']<=0||!$r['transaction_date']))throw new RuntimeException('Payment row '.$r['row_number'].' must be matched to an import and have a date and amount.');}
 $u=current_user();$new=0;$matched=0;$skipped=0;db()->beginTransaction();try{$lock=db()->prepare('SELECT confirmed_at FROM accounts_import_vat_statements WHERE id=? FOR UPDATE');$lock->execute([$id]);if($lock->fetchColumn()){db()->commit();return import_vat_statement($id);}foreach($active as$r){if($r['row_kind']==='liability'){if($r['match_status']==='already_imported'){$skipped++;continue;}$total=round((float)$r['import_vat_amount']+(float)$r['other_charge_amount'],2);db()->prepare('INSERT INTO accounts_import_vat_liabilities(import_date,import_month,supplier,description,reference,source_system,payment_arrangement,import_vat_amount,duty_amount,other_charge_amount,total_due,due_date,notes,created_by,created_by_name,source_statement_id,source_statement_row_id)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$r['transaction_date'],substr($r['transaction_date'],0,7),'',trim((string)$r['description'])?:'NamRA statement liability',$r['reference'],'NamRA statement','import_vat_account',$r['import_vat_amount'],0,$r['other_charge_amount'],$total,$r['due_date'],'Imported from '.$statement['original_filename'],(int)$u['id'],(string)$u['name'],$id,$r['id']]);$new++;}else{db()->prepare('INSERT INTO accounts_import_vat_payments(import_id,payment_date,amount,reference,payment_method,notes,created_by,created_by_name,source_statement_id,source_statement_row_id)VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([(int)$r['matched_import_id'],$r['transaction_date'],$r['payment_amount'],$r['reference']?:'NamRA statement','NamRA statement','Imported from '.$statement['original_filename'],(int)$u['id'],(string)$u['name'],$id,$r['id']]);$matched++;}}db()->prepare("UPDATE accounts_import_vat_statements SET status='confirmed',new_records=?,matched_payments=?,duplicates_skipped=?,confirmed_by=?,confirmed_by_name=?,confirmed_at=NOW() WHERE id=? AND confirmed_at IS NULL")->execute([$new,$matched,$skipped,(int)$u['id'],(string)$u['name'],$id]);import_vat_statement_audit($id,'statement_confirmed',['new_records'=>$new,'matched_payments'=>$matched,'duplicates_skipped'=>$skipped]);db()->commit();return import_vat_statement($id);}catch(Throwable$e){db()->rollBack();throw$e;}}
function im_upload(int$importId,?int$paymentId=null):void{if(empty($_FILES['files']['name']))return;$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','application/pdf'=>'pdf'];$dir=BASE_PATH.'/uploads/import-vat';if(!is_dir($dir)&&!mkdir($dir,0750,true)&&!is_dir($dir))throw new RuntimeException('Protected document storage is unavailable.');foreach((array)$_FILES['files']['name']as$i=>$name){if((int)$_FILES['files']['error'][$i]!==UPLOAD_ERR_OK)throw new RuntimeException('A document did not upload successfully.');$tmp=(string)$_FILES['files']['tmp_name'][$i];$size=(int)$_FILES['files']['size'][$i];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($tmp)?:'';if(!isset($allowed[$mime])||$size>25*1024*1024)throw new RuntimeException('Documents must be PDF, JPG, PNG or WEBP and no larger than 25 MB.');$stored=bin2hex(random_bytes(24)).'.'.$allowed[$mime];if(!move_uploaded_file($tmp,$dir.'/'.$stored))throw new RuntimeException('A document could not be stored.');db()->prepare('INSERT INTO accounts_import_vat_documents(import_id,payment_id,document_type,original_filename,stored_filename,mime_type,file_size,uploaded_by)VALUES(?,?,?,?,?,?,?,?)')->execute([$importId,$paymentId,(string)($_POST['document_type']??'other'),mb_substr(basename((string)$name),0,255),$stored,$mime,$size,(int)(current_user()['id']??0)]);}}
try{$action=(string)($_REQUEST['action']??'list');$month=import_vat_month((string)($_REQUEST['month']??date('Y-m')));$view=(string)($_REQUEST['view']??'imports');
 if($action==='statement_history')im_reply(['ok'=>true,'data'=>import_vat_statement_history()]);
